"use client";
import React from "react";
import Destinations from "../../after-your-booking/destinations";

const Climate = () => {
  return (
    <main className="tw-font-display tw-bg-white">
      {/* Hero */}
      <section className="tw-relative tw-overflow-hidden">
        <div
          className="tw-absolute tw-inset-0 tw-bg-cover tw-bg-center"
          style={{ backgroundImage: "url('/images/naturebanner.jpg')" }}
          aria-hidden="true"
        />
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background:
              "linear-gradient(180deg, rgba(20,16,28,0.45) 0%, rgba(20,16,28,0.55) 55%, rgba(20,16,28,0.8) 100%)",
          }}
          aria-hidden="true"
        />
        <div className="tw-relative tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-24 md:tw-py-32">
          <div className="tw-max-w-[760px]">
            <span className="tw-inline-flex tw-items-center tw-gap-2 tw-rounded-full tw-bg-white/10 tw-border tw-border-solid tw-border-white/20 tw-px-4 tw-py-1.5 tw-text-[13px] tw-font-semibold tw-text-white tw-backdrop-blur">
              Climate Commitment
            </span>
            <h1 className="tw-mt-5 tw-text-[clamp(30px,4.5vw,52px)] tw-font-bold tw-tracking-tight tw-leading-[1.05] tw-text-white tw-m-0">
              Our Commitment to Reducing Environmental Impact
            </h1>
            <p className="tw-mt-5 tw-mb-0 tw-text-[17px] tw-leading-[1.6] tw-text-white/85 tw-max-w-[60ch]">
              Making sustainable tourism the standard, not the exception — for a
              healthier planet and stronger communities.
            </p>
          </div>
        </div>
      </section>

      {/* Intro */}
      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[820px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-text-center">
          <h2 className="tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            Making Sustainable Tourism the Standard, Not the Exception
          </h2>
          <p className="tw-mt-5 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
            Our mission is to reshape the tourism sector into one that actively
            champions sustainability and responsibility at every level. Our
            vision for 2030 is to establish ourselves as the leading platform for
            adventure travel, where every tour operator integrates sustainability
            into their operations. By embracing and promoting sustainable
            practices, we are committed to making responsible tourism the
            expected norm — creating a lasting, positive legacy for future
            generations while enriching the travel experience for all.
          </p>
        </div>
      </section>

      {/* Citizens */}
      <section id="citizens" className="tw-scroll-mt-20 tw-pb-12 md:tw-pb-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div>
              <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
                People
              </span>
              <h2 className="tw-mt-2 tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                Citizens
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Our team is a vibrant mix of people from over 40 different
                nations, all working together toward a shared mission of creating
                positive change. We provide an inclusive environment where
                everyone feels valued, respected, and empowered — offering
                flexible hours, the option to work remotely, and mental health
                resources to ensure our employees thrive.
              </p>
              <p className="tw-mt-3 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                We are equally committed to ensuring fair and ethical working
                conditions for all those involved in our organized adventures.
                While tourism can sometimes have negative effects on certain
                destinations, we strive to ensure our adventures are responsible,
                equitable, and provide positive benefits to all stakeholders.
              </p>
            </div>
            <div>
              <img
                src="/images/mauidance.webp"
                alt="Cultural dance"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
          </div>
        </div>
      </section>

      {/* Earth */}
      <section
        id="earth"
        className="tw-scroll-mt-20 tw-py-12 md:tw-py-16 tw-bg-[#faf9fc]"
      >
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div className="tw-order-2 lg:tw-order-1">
              <img
                src="/images/kanguru.webp"
                alt="Wildlife"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
            <div className="tw-order-1 lg:tw-order-2">
              <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
                Planet
              </span>
              <h2 className="tw-mt-2 tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                Earth
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                We recognize the importance of animal welfare in responsible
                travel and are proud to align with the guidelines established by
                Intrepid Travel and World Animal Protection. We encourage all of
                our operators to adopt these guidelines when crafting itineraries
                and choosing suppliers.
              </p>
              <p className="tw-mt-3 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Central to our sustainability efforts is the Measure, Reduce,
                Compensate framework. We are committed to setting climate action
                targets in line with the Paris Climate Agreement and recognized as
                science-based targets — focusing on measuring and reducing
                emissions while limiting global warming.
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* Progress */}
      <section id="progress" className="tw-scroll-mt-20 tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[1320px] tw-px-6 md:tw-px-8 lg:tw-px-10">
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-[1.4fr_1fr] tw-gap-10 lg:tw-gap-14 tw-items-center">
            <div>
              <span className="tw-text-[13px] tw-font-semibold tw-uppercase tw-tracking-wider tw-text-[#854ec9]">
                Prosperity
              </span>
              <h2 className="tw-mt-2 tw-text-[clamp(24px,3vw,34px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
                Long-term Economic Progress
              </h2>
              <p className="tw-mt-4 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Our goal is to align with key Sustainable Development Goals such
                as No Poverty, Decent Work and Economic Growth, and Partnership
                for the Goals. The tourism sector has the power to provide
                employment, stimulate local economies, and increase foreign
                exchange — so we advocate for sustainable tourism practices that
                deliver lasting positive outcomes.
              </p>
              <p className="tw-mt-3 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                By partnering with operators who hire local guides and support
                locally-owned accommodations, restaurants, and businesses, we help
                drive economic growth while preserving local cultures, traditions,
                and ecosystems.
              </p>
              <p className="tw-mt-3 tw-mb-0 tw-text-[15px] tw-leading-[1.7] tw-text-[#5d556c]">
                Partnerships play a key role in reaching our objectives. By
                working together with stakeholders across the tourism sector, we
                can raise environmental awareness, conserve natural resources, and
                safeguard wildlife and biodiversity — building a world where
                everyone has the opportunity to flourish.
              </p>
            </div>
            <div>
              <img
                src="/images/hippy.jpg"
                alt="Responsible traveler"
                loading="lazy"
                className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
              />
            </div>
          </div>
        </div>
      </section>

      <Destinations />
    </main>
  );
};

export default Climate;
